          texto:
            "El otro personaje decisivo es Lheureux, el comerciante de telas que también presta dinero. Es amable, discreto y paciente, nunca presiona, siempre ofrece un plazo más largo, y es quien acabará matando a Emma con papel timbrado. Merece que se le vigile desde su primera escena.",
