          texto:
            "El 31 de enero de 1857, Gustave Flaubert compareció ante el tribunal correccional de París acusado de ultraje a la moral pública y a la religión, junto con el director de la revista y el impresor. El fiscal se llamaba Ernest Pinard y llevaba el caso muy preparado.",
